/**
 * StaticReportDemoView — dev-only showcase for the E25 report panel.
 *
 * Renders StaticReportPanel against the two REAL report fixtures under
 * `public/report-demo/` (generated by the env-gated Rust E2E: the
 * recorder's always-covered perspective and an enemy's 43%-coverage
 * perspective of the same match). Not registered in production builds —
 * the router only mounts it when `import.meta.env.DEV`.
 */
import { defineComponent, ref } from "vue";
import StaticReportPanel from "@/features/holographic/StaticReportPanel";
import type { StaticReport } from "@/api";

const FIXTURES = ["recorder", "enemy"] as const;

export default defineComponent({
  name: "StaticReportDemoView",
  setup() {
    const which = ref<(typeof FIXTURES)[number]>("recorder");
    const report = ref<StaticReport | null>(null);
    const load = async (name: (typeof FIXTURES)[number]) => {
      which.value = name;
      report.value = null;
      const res = await fetch(`${import.meta.env.BASE_URL}report-demo/${name}.json`);
      report.value = (await res.json()) as StaticReport;
    };
    void load("recorder");
    return () => (
      <div style="display:flex;align-items:flex-start;justify-content:center;min-height:100vh;background:#0d1117;padding:24px;box-sizing:border-box">
        <div style="display:flex;flex-direction:column;gap:10px;align-items:center">
          {FIXTURES.map((f) => (
            <button
              key={f}
              onClick={() => void load(f)}
              style={`padding:4px 12px;border-radius:6px;border:1px solid #2a3342;background:${which.value === f ? "#1d2634" : "transparent"};color:#d6dde8;cursor:pointer`}
            >
              {f}
            </button>
          ))}
        </div>
        <div style="margin-left:16px">
          {report.value ? (
            <StaticReportPanel
              report={report.value}
              onPick={() => {
                /* the demo has one report per fixture — switching
                 * perspectives needs the app's roster; keep it no-op. */
              }}
              onClose={() => {
                /* demo stays open */
              }}
            />
          ) : (
            <div style="color:#8b96a5">loading…</div>
          )}
        </div>
      </div>
    );
  },
});
